insert into public.style_anchors (slug, label, anchor_text, sort_order, image_url) values
('minimalist', 'Minimalist', 'fashion post. Style: minimalist, clean basics, capsule wardrobe. Neutral palette, tailored trousers, white tee, quality knits, understated silhouettes. Brands: COS, Everlane, Uniqlo.', 1, 'https://picsum.photos/seed/style-minimalist/600/800'),
('old_money', 'Old Money', 'fashion post. Style: old money, quiet luxury, classic. Cashmere, camel coat, loafers, trench, pearls, tailored blazer, polished timeless dressing. Brands: The Row, Ralph Lauren, Toteme.', 2, 'https://picsum.photos/seed/style-oldmoney/600/800'),
('streetwear', 'Streetwear', 'fashion post. Style: streetwear, hype, sneakers. Oversized hoodie, graphic tee, cargo pants, baggy denim, Jordans, caps, layered fits. Brands: Nike, Stüssy, Carhartt WIP.', 3, 'https://picsum.photos/seed/style-street/600/800'),
('athleisure', 'Athleisure', 'fashion post. Style: athleisure, activewear, gym to street. Leggings, matching sets, sports bra, zip-up, sneakers, comfortable performance fabrics. Brands: Lululemon, Alo Yoga, Nike.', 4, 'https://picsum.photos/seed/style-athleisure/600/800'),
('workwear', 'Workwear', 'fashion post. Style: workwear, office, smart. Tailored trousers, blazer, button-down, pencil skirt, pointed flats, polished 9-to-5 outfits. Brands: J.Crew, Aritzia, Theory.', 5, 'https://picsum.photos/seed/style-work/600/800'),
('scandi', 'Scandi', 'fashion post. Style: scandi, Scandinavian, effortless. Oversized blazer, straight-leg jeans, chunky knit, muted tones, relaxed proportions, clean layering. Brands: Ganni, COS, Toteme.', 6, 'https://picsum.photos/seed/style-scandi/600/800'),
('model_off_duty', 'Model Off Duty', 'fashion post. Style: model off duty, clean girl, effortless cool. Straight jeans, white tank, leather jacket, slicked-back hair, sneakers or boots, minimal jewelry. Brands: Aritzia, Zara, Levi''s.', 7, 'https://picsum.photos/seed/style-mod/600/800'),
('gorpcore', 'Gorpcore', 'fashion post. Style: gorpcore, outdoor, technical. Puffer, fleece, hiking boots, shell jacket, cargo, trail runners, functional layered outdoor wear. Brands: Arc''teryx, Patagonia, Salomon.', 8, 'https://picsum.photos/seed/style-gorp/600/800'),
('coastal', 'Coastal', 'fashion post. Style: coastal, beachy, breezy. Linen sets, white dress, sandals, raffia bag, striped knits, relaxed summer vacation dressing. Brands: Reformation, Madewell, Zara.', 9, 'https://picsum.photos/seed/style-coastal/600/800'),
('cottagecore', 'Cottagecore', 'fashion post. Style: cottagecore, romantic, prairie. Floral midi dress, puff sleeves, linen, smocking, straw hat, soft pastoral vintage feel. Brands: Free People, Reformation, Anthropologie.', 10, 'https://picsum.photos/seed/style-cottage/600/800'),
('y2k', 'Y2K', 'fashion post. Style: Y2K, 2000s revival, playful. Low-rise jeans, baby tee, mini skirt, butterfly clips, metallics, rhinestones, going-out cami. Brands: Princess Polly, Urban Outfitters, Miu Miu.', 11, 'https://picsum.photos/seed/style-y2k/600/800'),
('preppy', 'Preppy', 'fashion post. Style: preppy, collegiate, classic American. Polo, cable knit sweater, pleated skirt, chinos, loafers, stripes, tennis and country club looks. Brands: Ralph Lauren, J.Crew, Abercrombie & Fitch.', 12, 'https://picsum.photos/seed/style-preppy/600/800'),
('glam', 'Glam', 'fashion post. Style: glam, going out, night out. Mini dress, satin, sequins, corset top, heels, statement bag, party and date-night outfits. Brands: Princess Polly, Zara, Saint Laurent.', 13, 'https://picsum.photos/seed/style-glam/600/800'),
('vintage', 'Vintage', 'fashion post. Style: vintage, thrifted, retro. Secondhand denim, 70s and 90s pieces, leather jacket, unique one-of-a-kind finds, mixed eras. Brands: Levi''s, Coach, Gap.', 14, 'https://picsum.photos/seed/style-vintage/600/800'),
('boho', 'Boho', 'fashion post. Style: boho, bohemian, free-spirited. Flowy maxi dress, crochet, fringe, suede, layered jewelry, earthy prints, festival looks. Brands: Free People, Anthropologie, Urban Outfitters.', 15, 'https://picsum.photos/seed/style-boho/600/800'),
('grunge', 'Grunge', 'fashion post. Style: grunge, alternative, edgy. Black denim, band tee, combat boots, plaid flannel, leather jacket, ripped tights, dark layered looks. Brands: Urban Outfitters, Dr. Martens, Levi''s.', 16, 'https://picsum.photos/seed/style-grunge/600/800'),
('coquette', 'Coquette', 'fashion post. Style: coquette, balletcore, girly. Bows, lace, ballet flats, wrap cardigan, soft pink, ribbon details, delicate feminine pieces. Brands: Miu Miu, Sandy Liang, Free People.', 17, 'https://picsum.photos/seed/style-coquette/600/800'),
('western', 'Western', 'fashion post. Style: western, cowgirl, americana. Cowboy boots, denim on denim, fringe jacket, suede, belt buckle, prairie skirt, rodeo-inspired outfits. Brands: Levi''s, Free People, Ralph Lauren.', 18, 'https://picsum.photos/seed/style-western/600/800');
